#!/usr/bin/env bash
# runs set-release-version.sh against temporary copies of a Cargo.toml and a
# Cargo.lock, and the committed cli/ files, checking the exit status, the cause
# the script names, and what the files hold afterwards.
set -euo pipefail

scripts="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
set_version="${scripts}/set-release-version.sh"
committed="$(cd "${scripts}/../../cli" && pwd)"
work="$(mktemp -d)"
trap 'rm -rf -- "$work"' EXIT

# the dependencies and the other lock entry hold the placeholder too, so a case
# fails if the script replaces anything but the marshal-cli version.
manifest='[workspace]
members = ["."]

[package]
name = "marshal-cli"
version = "0.0.0-dev"
edition = "2024"

[dependencies]
example = { version = "0.0.0-dev" }

[dependencies.other]
version = "0.0.0-dev"
'
lockfile='# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "example"
version = "0.0.0-dev"

[[package]]
name = "marshal-cli"
version = "0.0.0-dev"
dependencies = [
 "example",
]
'

failures=0
fail() {
  echo "FAIL $*" >&2
  failures=$((failures + 1))
}

fixture() {
  mkdir -p "$1"
  printf '%s' "${2:-$manifest}" >"${1}/Cargo.toml"
  printf '%s' "${3:-$lockfile}" >"${1}/Cargo.lock"
}

# expect <case> <exit status> <text the output must contain> <version> <directory>
expect() {
  local name="$1" want_status="$2" want_text="$3" output status=0
  shift 3
  output="$(bash "$set_version" "$@" 2>&1)" || status=$?
  if [[ $status -ne $want_status ]]; then
    fail "${name}: exit ${status}, expected ${want_status}: ${output}"
    return 1
  elif [[ "$output" != *"$want_text"* ]]; then
    fail "${name}: the output does not contain '${want_text}': ${output}"
    return 1
  fi
}

# holds <case> <file> <expected content>, ignoring trailing newlines on both sides.
holds() {
  if [[ "$(cat "$2")" != "$(printf '%s' "$3")" ]]; then
    fail "${1}: $(basename "$2") holds:
$(cat "$2")"
    return 1
  fi
}

with_version() {
  printf '%s' "$1" | awk -v version="$2" '
    /^name = "marshal-cli"$/ { print; target = 1; next }
    target && /^version = / { print "version = \"" version "\""; target = 0; next }
    { print }
  '
}

case_dir="${work}/release"
fixture "$case_dir"
if expect "a release version" 0 "Set the CLI's version to 1.2.3" 1.2.3 "$case_dir" \
  && holds "a release version" "${case_dir}/Cargo.toml" "$(with_version "$manifest" 1.2.3)" \
  && holds "a release version" "${case_dir}/Cargo.lock" "$(with_version "$lockfile" 1.2.3)"; then
  echo "ok   a release version"
fi

case_dir="${work}/prerelease"
fixture "$case_dir"
if expect "a prerelease version" 0 "Set the CLI's version to 0.0.0-dryrun.42" 0.0.0-dryrun.42 "$case_dir" \
  && holds "a prerelease version" "${case_dir}/Cargo.toml" "$(with_version "$manifest" 0.0.0-dryrun.42)" \
  && holds "a prerelease version" "${case_dir}/Cargo.lock" "$(with_version "$lockfile" 0.0.0-dryrun.42)"; then
  echo "ok   a prerelease version"
fi

for invalid in v1.2.3 1.2 1.2.3+build.1 01.2.3 1.2.3- ""; do
  case_dir="${work}/invalid-${invalid:-empty}"
  fixture "$case_dir"
  if expect "the invalid version '${invalid}'" 1 "is not X.Y.Z or X.Y.Z-<prerelease>" "$invalid" "$case_dir" \
    && holds "the invalid version '${invalid}'" "${case_dir}/Cargo.toml" "$manifest" \
    && holds "the invalid version '${invalid}'" "${case_dir}/Cargo.lock" "$lockfile"; then
    echo "ok   the invalid version '${invalid}'"
  fi
done

released_manifest="$(with_version "$manifest" 0.1.0)"
case_dir="${work}/no-placeholder"
fixture "$case_dir" "$released_manifest"
if expect "a Cargo.toml without the placeholder" 1 "holds 0.1.0 as [package] version, not the placeholder 0.0.0-dev" 1.2.3 "$case_dir" \
  && holds "a Cargo.toml without the placeholder" "${case_dir}/Cargo.toml" "$released_manifest" \
  && holds "a Cargo.toml without the placeholder" "${case_dir}/Cargo.lock" "$lockfile"; then
  echo "ok   a Cargo.toml without the placeholder"
fi

duplicate_lockfile="${lockfile}
[[package]]
name = \"marshal-cli\"
version = \"0.0.0-dev\"
"
case_dir="${work}/duplicate"
fixture "$case_dir" "$manifest" "$duplicate_lockfile"
if expect "a Cargo.lock with two marshal-cli entries" 1 "has 2 marshal-cli version lines, not exactly one" 1.2.3 "$case_dir" \
  && holds "a Cargo.lock with two marshal-cli entries" "${case_dir}/Cargo.toml" "$manifest" \
  && holds "a Cargo.lock with two marshal-cli entries" "${case_dir}/Cargo.lock" "$duplicate_lockfile"; then
  echo "ok   a Cargo.lock with two marshal-cli entries"
fi

crlf_manifest="$(printf '%s' "$manifest" | sed 's/$/\r/')"$'\n'
crlf_lockfile="$(printf '%s' "$lockfile" | sed 's/$/\r/')"$'\n'
case_dir="${work}/crlf"
fixture "$case_dir" "$crlf_manifest" "$crlf_lockfile"
if expect "CRLF files" 0 "Set the CLI's version to 1.2.3" 1.2.3 "$case_dir" \
  && holds "CRLF files" "${case_dir}/Cargo.toml" "$(with_version "$manifest" 1.2.3 | sed 's/$/\r/')" \
  && holds "CRLF files" "${case_dir}/Cargo.lock" "$(with_version "$lockfile" 1.2.3 | sed 's/$/\r/')"; then
  echo "ok   CRLF files keep their line endings"
fi

# main must keep the placeholder, or every release build leg refuses.
case_dir="${work}/committed"
mkdir -p "$case_dir"
cp "${committed}/Cargo.toml" "${committed}/Cargo.lock" "$case_dir"
if expect "the committed cli/ files" 0 "Set the CLI's version to 0.0.0-dryrun.1" 0.0.0-dryrun.1 "$case_dir"; then
  echo "ok   the committed cli/ files hold the placeholder"
fi

if [[ $failures -ne 0 ]]; then
  echo "${failures} set-release-version case(s) failed." >&2
  exit 1
fi
echo "All set-release-version cases passed."
